def p(text='',red=False,style=None,center=False,italic=False):
 q=D.add_paragraph(style=style);r=q.add_run(text);r.italic=italic;r.font.color.rgb=RGBColor.from_string(RED if red else '000000');q.paragraph_format.widow_control=True
