def diagram(filename,boxes,edges,note):
 im=Image.new('RGB',(1800,1050),'white');dr=ImageDraw.Draw(im);font=ImageFont.truetype('C:/Windows/Fonts/times.ttf',30)
 for a,b in edges:
  aa=boxes[a][0];bb=boxes[b][0];x1=(aa[0]+aa[2])/2;y1=aa[3];x2=(bb[0]+bb[2])/2;y2=bb[1]
  if y2<y1:x1=aa[2];y1=(aa[1]+aa[3])/2;x2=bb[0];y2=(bb[1]+bb[3])/2
  points=[(x1,y1),(x2,y2)]
  if filename=='gmr.png' and (a,b)==('E','O'):points=[(1330,90),(1360,90),(1360,510),(1000,510)]
  elif filename=='gmr.png' and a=='Q':points=[(1390,410),(1150,460),(1000,480)]
  elif filename=='architecture.png' and a=='L':points=[(840,880),(960,880)]
  x1,y1=points[-2];x2,y2=points[-1]
  dr.line(points,fill='#555',width=4);ang=math.atan2(y2-y1,x2-x1);dr.polygon([(x2,y2),(x2-18*math.cos(ang-.4),y2-18*math.sin(ang-.4)),(x2-18*math.cos(ang+.4),y2-18*math.sin(ang+.4))],fill='#555')
 for rect,text in boxes.values():
  dr.rounded_rectangle(rect,12,fill='#F4F4F4',outline='black',width=3);ls=text.split('\n');y=(rect[1]+rect[3]-len(ls)*36)/2
  for line in ls:dr.text(((rect[0]+rect[2]-dr.textlength(line,font=font))/2,y),line,font=font,fill='black');y+=36
 dr.text((35,1000),note,font=ImageFont.truetype('C:/Windows/Fonts/times.ttf',24),fill='#C00000');im.save(B/filename,dpi=(300,300))
